  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Alamat memori dari variabel lain.','[{"key": "A", "text": "Tipe data dari variabel lain."}, {"key": "B", "text": "Nama dari variabel lain."}, {"key": "C", "text": "Jika sebuah fungsi rekursif tidak memiliki base case (kondisi berhenti), apa yang akan terjadi saat program dijalankan?"}, {"key": "D", "text": "Program akan berhenti dengan normal."}]'::jsonb,'B','Sintaks yang benar dan standar di C++ untuk mendeklarasikan sebuah array statis bernama array yang dapat menampung 10 elemen bertipe integer adalah int array[10];.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Fungsi akan mengembalikan nilai null.','[{"key": "A", "text": "Terjadi compile error."}, {"key": "B", "text": "Terjadi stack overflow."}, {"key": "C", "text": "Manakah dari sintaks berikut yang digunakan untuk mendeklarasikan sebuah array integer dengan 10 elemen di C++?"}, {"key": "D", "text": "array int[10];"}]'::jsonb,'B','Tujuan utama dari proses normalisasi dalam desain basis data adalah untuk mengorganisir tabel dan kolom agar dapat mengurangi pengulangan data (redudansi) serta mencegah masalah integritas data (anomali) saat melakukan operasi INSERT, UPDATE, atau DELETE.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'int array[10];','[{"key": "A", "text": "int array = new int(10);"}, {"key": "B", "text": "array<int> array(10);"}, {"key": "C", "text": "Tujuan utama dari normalisasi database adalah..."}, {"key": "D", "text": "Mempercepat proses query."}]'::jsonb,'B','Query ini adalah cara yang benar untuk menggabungkan data dari tabel Pelanggan dan Tagihan. Klausa INNER JOIN digunakan untuk menghubungkan kedua tabel berdasarkan kolom kunci (ID_Pelanggan) yang sama, sehingga nama pelanggan dapat ditampilkan bersama data tagihannya.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Mengurangi redudansi data dan anomali data.','[{"key": "A", "text": "Menambah jumlah tabel dalam database."}, {"key": "B", "text": "Mengenkripsi data sensitif."}, {"key": "C", "text": "Perhatikan dua tabel berikut: Pelanggan (ID_Pelanggan, Nama, Alamat) dan Tagihan (ID_Tagihan, ID_Pelanggan, Bulan, Jumlah_kWh). Query SQL manakah yang benar untuk menampilkan Nama Pelanggan beserta Jumlah_kWh dari tabel tersebut?"}, {"key": "D", "text": "SELECT Nama, Jumlah_kWh FROM Pelanggan, Tagihan;"}]'::jsonb,'C','Untuk melakukan filter terhadap hasil dari fungsi agregasi seperti SUM(), klausa yang tepat untuk digunakan adalah HAVING. Klausa WHERE digunakan untuk memfilter baris sebelum diagregasi, sedangkan HAVING memfilter grup setelah diagregasi.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'SELECT Pelanggan.Nama, Tagihan.Jumlah_kWh FROM Pelanggan INNER JOIN Tagihan ON Pelanggan.ID_Pelanggan = Tagihan.ID_Pelanggan;','[{"key": "A", "text": "SELECT Nama, Jumlah_kWh FROM Pelanggan WHERE Pelanggan.ID_Pelanggan = Tagihan.ID_Pelanggan;"}, {"key": "B", "text": "SELECT Pelanggan.Nama, Tagihan.Jumlah_kWh FROM Pelanggan;"}, {"key": "C", "text": "Manakah query yang digunakan untuk mencari total penggunaan listrik (Jumlah_kWh) per pelanggan dan hanya menampilkan pelanggan dengan total penggunaan di atas 500 kWh?"}, {"key": "D", "text": "SELECT ID_Pelanggan, SUM(Jumlah_kWh) FROM Tagihan GROUP BY ID_Pelanggan WHERE SUM(Jumlah_kWh) > 500;"}]'::jsonb,'B','Perintah-perintah SQL seperti CREATE, ALTER, dan DROP digunakan untuk mendefinisikan, mengubah, atau menghapus struktur objek dalam database. Kategori perintah ini disebut sebagai Data Definition Language (DDL).','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'SELECT ID_Pelanggan, SUM(Jumlah_kWh) FROM Tagihan WHERE Jumlah_kWh > 500 GROUP BY ID_Pelanggan;','[{"key": "A", "text": "SELECT ID_Pelanggan, SUM(Jumlah_kWh) FROM Tagihan GROUP BY ID_Pelanggan HAVING SUM(Jumlah_kWh) > 500;"}, {"key": "B", "text": "SELECT ID_Pelanggan, SUM(Jumlah_kWh) FROM Tagihan HAVING SUM(Jumlah_kWh) > 500;"}, {"key": "C", "text": "Perintah SQL seperti CREATE TABLE, ALTER TABLE, dan DROP TABLE termasuk dalam kategori..."}, {"key": "D", "text": "Data Manipulation Language (DML)"}]'::jsonb,'B','Ini adalah definisi formal dari Bentuk Normal Kedua (2NF). Sebuah tabel harus memenuhi 1NF terlebih dahulu, dan kemudian setiap atribut yang bukan bagian dari kunci utama harus bergantung sepenuhnya pada keseluruhan kunci utama, bukan hanya sebagian darinya.','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Data Definition Language (DDL)','[{"key": "A", "text": "Data Control Language (DCL)"}, {"key": "B", "text": "Transaction Control Language (TCL)"}, {"key": "C", "text": "Sebuah tabel dikatakan memenuhi Bentuk Normal Kedua (2NF) jika..."}, {"key": "D", "text": "Telah memenuhi syarat dasar di mana semua atribut hanya berisi nilai-nilai data yang bersifat atomik atau tunggal."}]'::jsonb,'A','Network Layer (Layer 3) dalam model OSI bertanggung jawab untuk pengalamatan logis (seperti IP address) dan menentukan rute (routing) terbaik untuk pengiriman paket data melintasi berbagai jaringan.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Telah memenuhi 1NF dan semua atribut non-kunci memiliki ketergantungan fungsional penuh pada primary key.','[{"key": "A", "text": "Telah memenuhi 2NF dan semua atribut non-kunci tidak memiliki ketergantungan transitif pada primary key utama."}, {"key": "B", "text": "Telah memenuhi aturan integritas referensial di mana semua foreign key merujuk pada nilai primary key yang ada."}, {"key": "C", "text": "Pada model referensi OSI, layer manakah yang bertanggung jawab untuk melakukan routing paket data antar jaringan?"}, {"key": "D", "text": "Network Layer"}]'::jsonb,'A','Alamat network didapatkan dengan melakukan operasi bitwise AND antara alamat IP dan subnet mask. Dengan subnet mask 255.255.255.0 atau /24, tiga oktet pertama (192.168.10) adalah bagian network, dan oktet terakhir disetel menjadi 0.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Data Link Layer','[{"key": "A", "text": "Physical Layer"}, {"key": "B", "text": "Transport Layer"}, {"key": "C", "text": "Diberikan alamat IP 192.168.10.50 dengan subnet mask 255.255.255.0. Manakah alamat network dari IP tersebut?"}, {"key": "D", "text": "192.168.10.0"}]'::jsonb,'B','Protokol TCP memastikan setiap paket data sampai ke tujuan dengan utuh dan dalam urutan yang benar. Ini dicapai melalui mekanisme seperti three-way handshake untuk memulai koneksi dan pengiriman acknowledgement untuk setiap data yang diterima.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'192.168.10.255','[{"key": "A", "text": "192.168.0.0"}, {"key": "B", "text": "192.168.10.1"}, {"key": "C", "text": "Apa fungsi utama dari protokol TCP (Transmission Control Protocol)?"}, {"key": "D", "text": "Menyediakan metode pengiriman data sangat cepat namun tanpa jaminan koneksi (connectionless)."}]'::jsonb,'D','Router adalah perangkat jaringan yang esensial untuk menghubungkan dua atau lebih segmen jaringan yang berbeda, seperti menghubungkan jaringan lokal kantor pusat dengan jaringan kantor cabang di lokasi lain.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menyediakan komunikasi yang andal dan berorientasi koneksi (reliable & connection-oriented).','[{"key": "A", "text": "Bertugas menerjemahkan nama domain yang mudah dibaca manusia menjadi alamat IP numerik (DNS)."}, {"key": "B", "text": "Bertanggung jawab mengatur alamat fisik perangkat keras (MAC address) di dalam jaringan area lokal."}, {"key": "C", "text": "Untuk menghubungkan jaringan komputer PLN di kantor pusat dengan kantor cabang di kota lain, perangkat jaringan yang paling penting adalah..."}, {"key": "D", "text": "Hub"}]'::jsonb,'D','Dalam jaringan dengan notasi CIDR /24, 24 bit pertama adalah alamat network dan 8 bit terakhir adalah untuk host. Alamat broadcast adalah alamat tertinggi dalam rentang tersebut, di mana semua bit host disetel ke 1. Untuk subnet 172.16.20.0, alamat broadcast-nya adalah 172.16.20.255.','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Switch','[{"key": "A", "text": "Repeater"}, {"key": "B", "text": "Router"}, {"key": "C", "text": "Manakah dari berikut ini yang merupakan alamat broadcast untuk jaringan 172.16.20.0/24?"}, {"key": "D", "text": "172.16.20.0"}]'::jsonb,'B','Presentation Layer (Layer 6) berfungsi sebagai penerjemah data. Lapisan ini memastikan data yang dikirim oleh Application Layer dapat dibaca oleh sistem penerima, dengan menangani tugas seperti format data, kompresi, dan enkripsi.','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'172.16.20.1','[{"key": "A", "text": "172.16.20.254"}, {"key": "B", "text": "172.16.20.255"}, {"key": "C", "text": "Lapisan OSI mana yang bertanggung jawab untuk format data, kompresi, dan enkripsi?"}, {"key": "D", "text": "Application Layer"}]'::jsonb,'B','Ini adalah perbedaan fundamental antara kedua jenis enkripsi. Enkripsi simetris cepat tetapi memiliki tantangan dalam distribusi kunci yang aman. Enkripsi asimetris memecahkan masalah distribusi kunci dengan menggunakan sepasang kunci (publik dan privat).','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Presentation Layer','[{"key": "A", "text": "Session Layer"}, {"key": "B", "text": "Transport Layer"}, {"key": "C", "text": "Apa perbedaan mendasar antara enkripsi simetris dan enkripsi asimetris?"}, {"key": "D", "text": "Enkripsi simetris lebih aman daripada asimetris."}]'::jsonb,'B','Fungsi hashing seperti SHA-256 mengubah input data menjadi sebuah string dengan panjang tetap yang unik (nilai hash). Jika data diubah sedikit saja, nilai hash akan berubah total. Ini digunakan untuk memverifikasi bahwa data tidak dimodifikasi selama transmisi.','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Enkripsi simetris menggunakan satu kunci untuk enkripsi dan dekripsi, sedangkan asimetris menggunakan dua kunci.','[{"key": "A", "text": "Enkripsi asimetris lebih cepat daripada simetris."}, {"key": "B", "text": "Enkripsi simetris hanya bisa digunakan untuk teks, sedangkan asimetris bisa untuk semua jenis data."}, {"key": "C", "text": "Fungsi hashing seperti SHA-256 digunakan untuk..."}, {"key": "D", "text": "Mengenkripsi data agar tidak bisa dibaca."}]'::jsonb,'C','Ikon gembok pada browser menandakan bahwa koneksi antara browser Anda dan server web diamankan menggunakan protokol kriptografi SSL/TLS. Protokol ini mengenkripsi semua data yang dipertukarkan, menciptakan koneksi HTTPS yang aman.','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Memastikan integritas data dengan menghasilkan nilai hash unik.','[{"key": "A", "text": "Menyembunyikan alamat IP pengguna."}, {"key": "B", "text": "Melakukan otentikasi pengguna dengan sertifikat digital."}, {"key": "C", "text": "Saat Anda mengakses situs web PLN Mobile dan melihat ikon gembok di browser, ini menandakan komunikasi antara browser Anda dan server diamankan menggunakan..."}, {"key": "D", "text": "FTP"}]'::jsonb,'A','AES (Advanced Encryption Standard) adalah algoritma enkripsi tipe block cipher yang menggunakan kunci yang sama untuk proses enkripsi dan dekripsi, sehingga ia tergolong dalam kategori enkripsi simetris.','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'SMTP','[{"key": "A", "text": "SSL/TLS"}, {"key": "B", "text": "Telnet"}, {"key": "C", "text": "Algoritma enkripsi AES (Advanced Encryption Standard) merupakan contoh dari jenis enkripsi..."}, {"key": "D", "text": "Simetris"}]'::jsonb,'B','Keamanan API modern mengandalkan dua pilar utama. Koneksi HTTPS (menggunakan SSL/TLS) akan mengenkripsi data selama transmisi, sementara token otorisasi (seperti OAuth atau JWT) memastikan bahwa hanya klien yang berwenang yang dapat mengakses data.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Asimetris','[{"key": "A", "text": "Hashing"}, {"key": "B", "text": "Steganografi"}, {"key": "C", "text": "Untuk mengamankan transfer data pembayaran listrik pelanggan melalui API, metode keamanan yang paling umum diterapkan adalah..."}, {"key": "D", "text": "Mengirim data dalam format plain text."}]'::jsonb,'B','Dalam arsitektur client-server, peran client adalah sebagai pihak yang menginisiasi permintaan (request) untuk mendapatkan data, layanan, atau sumber daya lainnya yang disediakan dan dikelola oleh server.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menggunakan token otorisasi dan koneksi HTTPS.','[{"key": "A", "text": "Membatasi akses berdasarkan waktu."}, {"key": "B", "text": "Hanya mengandalkan firewall di sisi server."}, {"key": "C", "text": "Dalam arsitektur client-server, manakah pernyataan yang paling tepat mendeskripsikan peran client?"}, {"key": "D", "text": "Menyimpan, mengelola, dan menyediakan data atau layanan."}]'::jsonb,'C','API (Application Programming Interface) berfungsi sebagai kontrak atau antarmuka yang mendefinisikan cara perangkat lunak yang berbeda dapat berkomunikasi satu sama lain, tanpa perlu mengetahui detail implementasi internal masing-masing.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Meminta layanan atau sumber daya dari server.','[{"key": "A", "text": "Menjadi perantara antara dua server."}, {"key": "B", "text": "Hanya bertanggung jawab pada tampilan antarmuka."}, {"key": "C", "text": "API (Application Programming Interface) berfungsi sebagai..."}, {"key": "D", "text": "Sebuah database terpusat yang berfungsi untuk menyimpan seluruh data dari suatu aplikasi."}]'::jsonb,'C','Untuk integrasi sistem industri seperti SCADA yang membutuhkan transmisi data real-time, digunakan protokol komunikasi khusus seperti Modbus atau DNP3. Dalam sistem yang lebih modern, integrasi juga sering dilakukan melalui API (misalnya REST atau MQTT).','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah antarmuka pengguna grafis (GUI) visual yang ditampilkan di layar aplikasi pengguna.','[{"key": "A", "text": "Jembatan komunikasi yang memungkinkan dua aplikasi berbeda untuk saling berinteraksi."}, {"key": "B", "text": "Sebuah sistem operasi dasar yang bertugas utama untuk menjalankan semua proses aplikasi."}, {"key": "C", "text": "Sistem SCADA di gardu induk PLN perlu mengirimkan data status operasional secara real-time ke pusat kendali. Metode integrasi yang paling umum digunakan untuk ini adalah melalui..."}, {"key": "D", "text": "Input data manual oleh operator."}]'::jsonb,'C','Tujuan utama implementasi sistem ERP (Enterprise Resource Planning) adalah untuk menciptakan satu sumber data terpusat (single source of truth) dengan mengintegrasikan berbagai proses bisnis seperti keuangan, SDM, logistik, dan produksi ke dalam satu platform.','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pengiriman file CSV setiap hari.','[{"key": "A", "text": "API atau protokol komunikasi data industri seperti Modbus/DNP3."}, {"key": "B", "text": "Email notifikasi."}, {"key": "C", "text": "Apa tujuan utama dari implementasi sistem ERP (Enterprise Resource Planning) di sebuah perusahaan besar seperti PLN?"}, {"key": "D", "text": "Berfungsi secara eksklusif hanya untuk mengelola semua data yang berkaitan dengan keuangan."}]'::jsonb,'A','Arsitektur Microservices adalah pendekatan pengembangan perangkat lunak di mana aplikasi besar dipecah menjadi kumpulan layanan-layanan kecil yang independen. Setiap layanan berjalan dalam prosesnya sendiri dan berkomunikasi dengan layanan lain melalui API.','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dibuat dengan tujuan spesifik untuk menggantikan seluruh peran dan fungsi seorang manajer.','[{"key": "A", "text": "Mengintegrasikan semua proses bisnis utama perusahaan ke dalam satu sistem terpusat."}, {"key": "B", "text": "Digunakan spesifik untuk proses pembuatan dan pengelolaan website profil utama perusahaan."}, {"key": "C", "text": "Arsitektur di mana aplikasi dibagi menjadi komponen-komponen kecil yang independen dan dapat dikembangkan serta di-deploy secara terpisah disebut..."}, {"key": "D", "text": "Microservices"}]'::jsonb,'B','SCADA adalah singkatan dari Supervisory Control and Data Acquisition, sebuah sistem arsitektur kontrol yang menggunakan komputer dan komunikasi data jaringan untuk pengawasan dan pengendalian proses industri atau infrastruktur dari jarak jauh.','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Client-Server','[{"key": "A", "text": "Monolitik"}, {"key": "B", "text": "Peer-to-Peer"}, {"key": "C", "text": "Dalam konteks jaringan listrik PLN, SCADA adalah singkatan dari..."}, {"key": "D", "text": "System Control and Data Automation"}]'::jsonb,'D','MQTT (Message Queuing Telemetry Transport) adalah protokol perpesanan ringan yang dirancang untuk koneksi dengan perangkat di lokasi terpencil yang memiliki keterbatasan bandwidth dan daya. Sifatnya yang efisien membuatnya sangat cocok untuk aplikasi IoT.','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Supervisory Control and Data Acquisition','[{"key": "A", "text": "Software Computation and Digital Access"}, {"key": "B", "text": "Secure Connection and Data Administration"}, {"key": "C", "text": "Protokol komunikasi yang ringan, berbasis publish-subscribe, dan sangat populer digunakan untuk perangkat IoT seperti smart meter karena efisiensi bandwidth dan dayanya adalah..."}, {"key": "D", "text": "HTTP"}]'::jsonb,'D','Telemetri adalah teknologi yang memungkinkan pengukuran, pengumpulan, dan pengiriman data secara otomatis dari sumber yang jauh atau tidak dapat diakses ke pusat pemantauan untuk dianalisis.','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'FTP','[{"key": "A", "text": "SMTP"}, {"key": "B", "text": "MQTT"}, {"key": "C", "text": "Proses pengukuran dan pengiriman data secara otomatis dari lokasi terpencil ke pusat pemantauan, seperti data tegangan dari gardu distribusi, disebut..."}, {"key": "D", "text": "Teleportasi"}]'::jsonb,'B','Untuk memantau besar beban listrik yang sedang digunakan pada suatu jaringan, parameter utama yang harus diukur adalah besar arus listrik yang mengalir. Oleh karena itu, sensor arus adalah komponen yang paling relevan.','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Telemarketing','[{"key": "A", "text": "Telekomunikasi"}, {"key": "B", "text": "Telemetri"}, {"key": "C", "text": "Sensor apakah yang paling relevan untuk dipasang di tiang listrik dalam skema smart grid untuk memantau beban puncak?"}, {"key": "D", "text": "Sensor suhu dan kelembaban"}]'::jsonb,'B','Modbus adalah protokol komunikasi serial yang telah menjadi standar de-facto di dunia industri. Protokol ini banyak digunakan untuk menghubungkan perangkat-perangkat otomasi industri seperti PLC, HMI, sensor, dan aktuator.','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sensor arus','[{"key": "A", "text": "Sensor cahaya"}, {"key": "B", "text": "Sensor gerak"}, {"key": "C", "text": "Protokol Modbus sering digunakan dalam lingkungan industri untuk..."}, {"key": "D", "text": "Menyediakan layanan streaming video dengan kualitas resolusi yang sangat tinggi."}]'::jsonb,'C','Konsep ini merupakan aplikasi inti dari Internet of Things (IoT), di mana objek fisik sehari-hari (seperti meteran listrik) dilengkapi dengan sensor dan konektivitas untuk terhubung ke internet, sehingga memungkinkan mereka mengumpulkan dan bertukar data.','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Komunikasi antara perangkat elektronik industri seperti PLC dan sensor.','[{"key": "A", "text": "Melakukan pengiriman berbagai macam surat elektronik (email) dalam jumlah besar."}, {"key": "B", "text": "Melakukan aktivitas penjelajahan berbagai situs web di jaringan internet global."}, {"key": "C", "text": "Konsep di mana jutaan meteran listrik pelanggan dapat mengirimkan data penggunaan secara real-time ke server PLN dan dapat dikendalikan dari jarak jauh adalah aplikasi utama dari..."}, {"key": "D", "text": "Augmented Reality"}]'::jsonb,'B','Dalam sistem SCADA, RTU adalah perangkat berbasis mikroprosesor yang ditempatkan di lokasi terpencil. Fungsinya adalah untuk menjadi antarmuka dengan sensor dan aktuator di lapangan, mengumpulkan data, dan mengirimkannya ke stasiun pusat (master station).','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Virtual Reality','[{"key": "A", "text": "Internet of Things (IoT)"}, {"key": "B", "text": "Cloud Computing"}, {"key": "C", "text": "Perangkat di lapangan yang berfungsi mengumpulkan data dari sensor dan mengirimkannya ke master station dalam sistem SCADA disebut..."}, {"key": "D", "text": "HMI (Human-Machine Interface)"}]'::jsonb,'B','Dengan data real-time dari sensor IoT yang tersebar di jaringan, PLN dapat mendeteksi potensi masalah (seperti trafo kelebihan beban) sebelum terjadi kegagalan, serta mengetahui lokasi gangguan secara akurat dan cepat, sehingga dapat mengurangi durasi pemadaman listrik.','AKDING',40);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'RTU (Remote Terminal Unit)','[{"key": "A", "text": "Server Database"}, {"key": "B", "text": "Router"}, {"key": "C", "text": "Manfaat utama penerapan IoT pada jaringan distribusi listrik PLN adalah..."}, {"key": "D", "text": "Bertujuan utama untuk mengurangi jumlah total karyawan yang saat ini bekerja di lapangan secara masif."}]'::jsonb,'A','','AKDING',41);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah algoritma pengurutan bekerja dengan strategi "divide and conquer", yaitu memecah array menjadi dua bagian, mengurutkan masing-masing bagian, lalu menggabungkannya kembali. Algoritma ini adalah...','[{"key": "A", "text": "Bubble Sort"}, {"key": "B", "text": "Insertion Sort"}, {"key": "C", "text": "Merge Sort"}, {"key": "D", "text": "Selection Sort"}]'::jsonb,'C','Merge Sort adalah contoh klasik dari algoritma yang menggunakan paradigma "divide and conquer". Ia secara rekursif membagi array menjadi dua hingga setiap subarray hanya memiliki satu elemen, kemudian menggabungkannya kembali dalam urutan yang benar.','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika Anda perlu mencari data pelanggan berdasarkan ID Pelanggan di sebuah array yang tidak terurut, algoritma pencarian manakah yang harus digunakan?','[{"key": "A", "text": "Binary Search"}, {"key": "B", "text": "Linear Search"}, {"key": "C", "text": "Jump Search"}, {"key": "D", "text": "Interpolation Search"}]'::jsonb,'B','Karena data tidak terurut, tidak ada cara lain selain memeriksa setiap elemen satu per satu dari awal hingga akhir sampai data yang dicari ditemukan. Metode ini disebut Linear Search. Binary Search tidak dapat digunakan karena mensyaratkan data terurut.','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Struktur data yang merepresentasikan hubungan hierarkis, seperti struktur organisasi di kantor PLN, adalah...','[{"key": "A", "text": "Queue"}, {"key": "B", "text": "Stack"}, {"key": "C", "text": "Tree"}, {"key": "D", "text": "Linked List"}]'::jsonb,'C','Struktur data Tree (pohon) secara alami merepresentasikan data yang memiliki hubungan hierarkis atau orang tua-anak (parent-child), seperti silsilah keluarga, struktur file, atau bagan organisasi perusahaan.','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam konteks pemodelan jaringan distribusi listrik PLN, di mana gardu induk dan gardu distribusi adalah simpul (node) dan kabel listrik adalah sisi (edge), struktur data yang paling tepat untuk digunakan adalah...','[{"key": "A", "text": "Graph"}, {"key": "B", "text": "Array"}, {"key": "C", "text": "Stack"}, {"key": "D", "text": "Hash Table"}]'::jsonb,'A','Struktur data Graph sangat ideal untuk memodelkan jaringan di mana terdapat titik-titik (simpul/vertex) yang terhubung oleh garis (sisi/edge). Ini sangat cocok untuk merepresentasikan jaringan listrik, jaringan komputer, atau peta jalan.','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perhatikan pseudocode berikut:','[{"key": "A", "text": "function hitung(n)"}, {"key": "B", "text": "jika n <= 1 maka"}, {"key": "C", "text": "kembalikan 1"}, {"key": "D", "text": "selain itu"}]'::jsonb,'A','Pseudocode tersebut adalah fungsi rekursif untuk menghitung faktorial. Kondisi n <= 1 adalah base case-nya. Untuk n > 1, ia mengembalikan n dikalikan dengan faktorial dari (n-1).','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'kembalikan n * hitung(n-1)','[{"key": "A", "text": "Pseudocode di atas merupakan implementasi dari fungsi..."}, {"key": "B", "text": "Faktorial"}, {"key": "C", "text": "Fibonacci"}, {"key": "D", "text": "Pangkat"}]'::jsonb,'D','Keunggulan utama dari Hash Table adalah kemampuannya untuk melakukan operasi (insert, delete, search) dalam waktu konstan atau O(1) pada kasus terbaik dan rata-rata. Ini dicapai dengan menghitung indeks array secara langsung dari nilai hash kunci.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Penjumlahan','[{"key": "A", "text": "Kompleksitas waktu (Big O notation) untuk mengakses elemen dalam sebuah Hash Table pada kasus terbaik (best-case) adalah..."}, {"key": "B", "text": "O(n²)"}, {"key": "C", "text": "O(n log n)"}, {"key": "D", "text": "O(n)"}]'::jsonb,'A','Kondisi if memerlukan kedua ekspresi untuk bernilai benar karena menggunakan operator && (AND). Meskipun x > 3 (5 > 3) bernilai benar, y < 5 (10 < 5) bernilai salah. Karena salah satu salah, maka keseluruhan kondisi bernilai salah, sehingga program akan mengeksekusi blok else.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'O(1)','[{"key": "A", "text": "Perhatikan potongan kode C++ berikut:"}, {"key": "B", "text": "int x = 5;"}, {"key": "C", "text": "int y = 10;"}, {"key": "D", "text": "if (x > 3 && y < 5) {"}]'::jsonb,'D','Pass by reference adalah mekanisme di mana alamat memori dari sebuah variabel yang dilewatkan ke fungsi, biasanya menggunakan pointer atau referensi. Hal ini memungkinkan fungsi untuk memodifikasi nilai variabel asli secara langsung.','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'// Blok A','[{"key": "A", "text": "} else {"}, {"key": "B", "text": "// Blok B"}, {"key": "C", "text": "}"}, {"key": "D", "text": "Blok kode manakah yang akan dieksekusi?"}]'::jsonb,'B','struct dan class adalah tipe data bentukan pengguna (user-defined) yang memungkinkan programmer untuk mengelompokkan variabel dari tipe data yang berbeda (seperti int, string, double) ke dalam satu objek logis.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Blok B','[{"key": "A", "text": "Blok A"}, {"key": "B", "text": "Keduanya dieksekusi"}, {"key": "C", "text": "Tidak ada yang dieksekusi"}, {"key": "D", "text": "Dalam pemrograman C++, mekanisme untuk mengirimkan salinan alamat memori sebuah variabel ke dalam fungsi, sehingga nilai variabel asli dapat diubah dari dalam fungsi tersebut, disebut..."}]'::jsonb,'A','Loop while akan terus dieksekusi selama kondisi i < 5 terpenuhi. Variabel i dimulai dari 0 dan bertambah satu setiap iterasi. Loop akan berjalan untuk i = 0, 1, 2, 3, 4. Ketika i menjadi 5, kondisi 5 < 5 menjadi salah dan loop berhenti. Jadi, blok kode dieksekusi sebanyak 5 kali.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pass by value','[{"key": "A", "text": "Pass by array"}, {"key": "B", "text": "Pass by copy"}, {"key": "C", "text": "Pass by reference"}, {"key": "D", "text": "Manakah dari berikut ini yang merupakan tujuan utama dari penggunaan struct atau class dalam C++?"}]'::jsonb,'A','Ini adalah jebakan umum. Di dalam if, pernyataan angka = 5 adalah operasi assignment (pengisian nilai), bukan perbandingan (==). Operasi assignment di C++ mengembalikan nilai yang diisikan, yaitu 5. Dalam konteks boolean, nilai selain 0 dianggap true. Jadi, kondisi if terpenuhi dan program mencetak "Lima".','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Untuk membuat sebuah perulangan kode (loop) bisa dieksekusi jauh lebih cepat.','[{"key": "A", "text": "Untuk menggabungkan beberapa tipe data yang berbeda ke dalam satu unit."}, {"key": "B", "text": "Sebagai metode utama untuk mendeklarasikan sebuah variabel yang bersifat global."}, {"key": "C", "text": "Untuk menangani berbagai operasi pembacaan dan penulisan data ke sebuah file."}, {"key": "D", "text": "Perhatikan loop berikut:"}]'::jsonb,'C','TRUNCATE adalah perintah DDL yang menghapus semua baris dari tabel dengan cepat. Operasi ini minimal logging-nya dan tidak bisa di-rollback, berbeda dengan DELETE yang merupakan operasi DML dan bisa di-rollback.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'int i = 0;','[{"key": "A", "text": "while (i < 5) {"}, {"key": "B", "text": "// code block"}, {"key": "C", "text": "i++;"}, {"key": "D", "text": "}"}]'::jsonb,'C','Foreign Key adalah sebuah kolom (atau kumpulan kolom) dalam sebuah tabel yang membangun hubungan antara data di dua tabel. Nilainya merujuk ke nilai Primary Key di tabel lain, menegakkan integritas referensial.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Berapa kali "code block" akan dieksekusi?','[{"key": "A", "text": "5 kali"}, {"key": "B", "text": "6 kali"}, {"key": "C", "text": "7 kali"}, {"key": "D", "text": "Tidak terbatas"}]'::jsonb,'D','LEFT JOIN akan mengembalikan semua baris dari tabel kiri (Pelanggan) dan baris yang cocok dari tabel kanan (Tagihan). Jika tidak ada kecocokan di tabel kanan, hasilnya adalah NULL. Ini cocok untuk kasus mencari pelanggan yang belum memiliki tagihan.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Apa output dari potongan kode C++ berikut?','[{"key": "A", "text": "#include <iostream>"}, {"key": "B", "text": "int main() {"}, {"key": "C", "text": "int angka = 10;"}, {"key": "D", "text": "if (angka = 5) {"}]'::jsonb,'A','Sintaks standar untuk memodifikasi data yang sudah ada di dalam tabel adalah menggunakan perintah UPDATE, diikuti nama tabel, klausa SET untuk menentukan kolom dan nilai baru, dan klausa WHERE untuk menspesifikasikan baris mana yang akan diubah.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'std::cout << "Lima";','[{"key": "A", "text": "} else {"}, {"key": "B", "text": "std::cout << \"Sepuluh\";"}, {"key": "C", "text": "}"}, {"key": "D", "text": "return 0;"}]'::jsonb,'C','Ketergantungan transitif terjadi ketika sebuah atribut non-kunci bergantung pada atribut non-kunci lainnya, bukan pada primary key. Untuk mencapai 3NF, tabel harus sudah dalam 2NF dan semua ketergantungan transitif harus dihilangkan.','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'}','[{"key": "A", "text": "Lima"}, {"key": "B", "text": "Sepuluh"}, {"key": "C", "text": "Tidak ada output"}, {"key": "D", "text": "Compile error"}]'::jsonb,'B','UDP (User Datagram Protocol) adalah protokol connectionless yang tidak menjamin pengiriman, urutan, atau integritas data. Keunggulannya adalah latensi yang rendah dan overhead yang kecil, cocok untuk aplikasi seperti streaming atau game online.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manakah pernyataan SQL yang benar untuk menghapus semua baris data dari tabel Log_Gangguan tanpa menghapus struktur tabelnya, dan tidak bisa di-rollback?','[{"key": "A", "text": "DELETE FROM Log_Gangguan;"}, {"key": "B", "text": "DROP TABLE Log_Gangguan;"}, {"key": "C", "text": "TRUNCATE TABLE Log_Gangguan;"}, {"key": "D", "text": "REMOVE ALL Log_Gangguan;"}]'::jsonb,'D','MAC (Media Access Control) Address adalah pengenal unik yang ditanamkan oleh pabrikan pada perangkat keras jaringan. Alamat ini digunakan untuk komunikasi pada level jaringan lokal (dalam segmen yang sama) dan beroperasi di Data Link Layer.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam desain database relasional, kolom di satu tabel yang merujuk ke primary key di tabel lain disebut...','[{"key": "A", "text": "Super Key"}, {"key": "B", "text": "Candidate Key"}, {"key": "C", "text": "Foreign Key"}, {"key": "D", "text": "Composite Key"}]'::jsonb,'A','Switch adalah perangkat cerdas yang beroperasi di Layer 2. Ia mempelajari alamat MAC dari perangkat yang terhubung ke setiap portnya dan hanya meneruskan data ke port tujuan yang spesifik, tidak seperti Hub yang menyiarkan ke semua port.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Untuk menampilkan semua data pelanggan dari tabel Pelanggan dan data tagihannya dari tabel Tagihan, termasuk pelanggan yang mungkin belum memiliki tagihan, query JOIN yang paling tepat adalah...','[{"key": "A", "text": "INNER JOIN"}, {"key": "B", "text": "RIGHT JOIN"}, {"key": "C", "text": "CROSS JOIN"}, {"key": "D", "text": "LEFT JOIN"}]'::jsonb,'A','Subnet mask /28 berarti 28 bit untuk network dan 4 bit sisanya untuk host (32 - 28 = 4). Jumlah total alamat yang bisa dibuat adalah 2⁴ = 16. Namun, dua alamat tidak bisa digunakan untuk host: satu untuk alamat network dan satu untuk alamat broadcast. Jadi, jumlah host maksimum adalah 16 - 2 = 14.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perintah SQL untuk mengubah alamat seorang pelanggan dengan ID_Pelanggan ''PLN001'' menjadi ''Jalan Baru'' di tabel Pelanggan adalah...','[{"key": "A", "text": "UPDATE Pelanggan SET Alamat=''Jalan Baru'' WHERE ID_Pelanggan=''PLN001'';"}, {"key": "B", "text": "MODIFY Pelanggan SET Alamat=''Jalan Baru'' WHERE ID_Pelanggan=''PLN001'';"}, {"key": "C", "text": "CHANGE Pelanggan (Alamat) TO ''Jalan Baru'' WHERE ID_Pelanggan=''PLN001'';"}, {"key": "D", "text": "INSERT INTO Pelanggan (Alamat) VALUES (''Jalan Baru'') WHERE ID_Pelanggan=''PLN001'';"}]'::jsonb,'B','DNS (Domain Name System) berfungsi seperti buku telepon untuk internet. Ia menerjemahkan nama domain yang mudah diingat manusia (misalnya, www.pln.co.id) menjadi alamat IP numerik yang dipahami oleh komputer untuk menemukan server di internet.','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah tabel dikatakan telah memenuhi Bentuk Normal Ketiga (3NF) jika telah memenuhi 2NF dan...','[{"key": "A", "text": "Semua atributnya bernilai atomik."}, {"key": "B", "text": "Tidak ada ketergantungan fungsional parsial."}, {"key": "C", "text": "Tidak ada ketergantungan transitif."}, {"key": "D", "text": "Semua kolom memiliki tipe data yang sama."}]'::jsonb,'C','Ini adalah perbedaan fundamental. Hub adalah perangkat "bodoh" di Layer 1 (Physical) yang hanya mengulang sinyal listrik ke semua port. Switch adalah perangkat "cerdas" di Layer 2 (Data Link) yang dapat membaca alamat MAC dan membuat keputusan penerusan data.','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Protokol yang menyediakan pengiriman data yang cepat namun tidak andal (connectionless) karena tidak ada mekanisme pengecekan paket adalah...','[{"key": "A", "text": "TCP"}, {"key": "B", "text": "UDP"}, {"key": "C", "text": "HTTP"}, {"key": "D", "text": "FTP"}]'::jsonb,'A','Tanda tangan digital menggunakan kriptografi asimetris untuk memastikan otentikasi (siapa pengirimnya), integritas (data tidak diubah), dan non-repudiation (pengirim tidak bisa menyangkal telah mengirim).','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Alamat fisik unik yang dimiliki oleh setiap kartu antarmuka jaringan (Network Interface Card) dan bekerja pada Data Link Layer disebut...','[{"key": "A", "text": "IP Address"}, {"key": "B", "text": "Port Number"}, {"key": "C", "text": "Network Address"}, {"key": "D", "text": "MAC Address"}]'::jsonb,'C','Dalam serangan MITM, penyerang menempatkan dirinya di antara dua pihak yang berkomunikasi, memungkinkan mereka untuk menyadap, membaca, dan bahkan memanipulasi data tanpa terdeteksi oleh kedua pihak tersebut.','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perangkat jaringan yang bekerja di Layer 2 (Data Link Layer) dan meneruskan paket data dengan melihat alamat MAC tujuan adalah...','[{"key": "A", "text": "Switch"}, {"key": "B", "text": "Hub"}, {"key": "C", "text": "Repeater"}, {"key": "D", "text": "Router"}]'::jsonb,'D','Firewall bertindak sebagai filter keamanan antara jaringan internal yang aman (misalnya, jaringan kantor PLN) dan jaringan eksternal yang tidak aman (internet). Ia mengontrol lalu lintas data berdasarkan seperangkat aturan.','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika sebuah jaringan memiliki subnet mask /28, berapa jumlah maksimum host yang dapat terhubung dalam jaringan tersebut?','[{"key": "A", "text": "14"}, {"key": "B", "text": "16"}, {"key": "C", "text": "30"}, {"key": "D", "text": "32"}]'::jsonb,'C','Sifat satu arah (one-way) dari fungsi hash berarti sangat sulit secara komputasional untuk merekayasa balik input asli hanya dari output hash-nya. Inilah sebabnya mengapa hash digunakan untuk menyimpan password.','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Layanan jaringan yang berfungsi untuk menerjemahkan nama domain (contoh: www.pln.co.id) menjadi alamat IP adalah...','[{"key": "A", "text": "DHCP"}, {"key": "B", "text": "DNS"}, {"key": "C", "text": "FTP"}, {"key": "D", "text": "SMTP"}]'::jsonb,'B','PKI adalah kerangka kerja teknologi, kebijakan, dan prosedur yang diperlukan untuk membuat, mengelola, mendistribusikan, menggunakan, menyimpan, dan mencabut sertifikat digital serta mengelola enkripsi kunci publik.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manakah dari berikut ini yang merupakan perbedaan utama antara Hub dan Switch?','[{"key": "A", "text": "Hub lebih cepat dari Switch."}, {"key": "B", "text": "Switch mengirim data ke semua port, sedangkan Hub hanya ke port tujuan."}, {"key": "C", "text": "Hub bekerja di Layer 1, sedangkan Switch bekerja di Layer 2."}, {"key": "D", "text": "Hub menggunakan alamat IP, sedangkan Switch menggunakan alamat MAC."}]'::jsonb,'C','Server adalah komponen dalam model client-server yang menunggu dan menanggapi permintaan dari client. Ia bertanggung jawab untuk menyediakan layanan, mengelola data, dan melakukan pemrosesan berat.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Untuk memverifikasi keaslian pengirim dan memastikan integritas data, teknologi yang menggunakan kunci privat pengirim untuk mengenkripsi hash dari pesan adalah...','[{"key": "A", "text": "Digital Signature (Tanda Tangan Digital)"}, {"key": "B", "text": "Firewall"}, {"key": "C", "text": "Symmetric Encryption"}, {"key": "D", "text": "Steganography"}]'::jsonb,'D','REST (Representational State Transfer) adalah gaya arsitektur yang menggunakan standar protokol web, termasuk metode HTTP (GET, POST, PUT, DELETE), untuk komunikasi antar sistem. Ini adalah pendekatan yang paling umum untuk membuat API saat ini.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Serangan siber di mana penyerang secara diam-diam menyadap dan mungkin mengubah komunikasi antara dua pihak tanpa sepengetahuan mereka disebut...','[{"key": "A", "text": "Phishing"}, {"key": "B", "text": "DDoS Attack"}, {"key": "C", "text": "Man-in-the-Middle (MITM) Attack"}, {"key": "D", "text": "SQL Injection"}]'::jsonb,'B','Ciri utama dari sistem terdistribusi adalah komponen-komponennya (komputer) tersebar di jaringan tetapi bekerja sama dan berkoordinasi untuk tampil sebagai satu sistem tunggal yang terpadu bagi pengguna akhir.','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perangkat keamanan jaringan yang berfungsi sebagai benteng pertahanan dengan menyaring lalu lintas data masuk dan keluar berdasarkan aturan keamanan yang telah ditentukan adalah...','[{"key": "A", "text": "Router"}, {"key": "B", "text": "Switch"}, {"key": "C", "text": "Modem"}, {"key": "D", "text": "Firewall"}]'::jsonb,'D','Modul EAM dalam sebuah ERP dirancang khusus untuk mengelola seluruh siklus hidup aset fisik suatu organisasi. Bagi PLN, ini mencakup semua infrastruktur kelistrikan dari pembangkit hingga jaringan distribusi.','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Hashing adalah proses satu arah. Ini berarti...','[{"key": "A", "text": "Data yang telah selesai di-hash dapat dengan mudah sekali dikembalikan ke bentuk data aslinya."}, {"key": "B", "text": "Proses hashing itu selalu memerlukan penggunaan dua kunci yang berbeda (publik dan privat)."}, {"key": "C", "text": "Data yang sudah di-hash secara praktis tidak mungkin dikembalikan ke bentuk aslinya."}, {"key": "D", "text": "Proses hashing hanya bisa diaplikasikan pada data yang memiliki format berupa teks murni saja."}]'::jsonb,'D','Big Data merujuk pada kumpulan data yang sangat besar dan kompleks yang tidak dapat dikelola atau diproses secara efektif menggunakan aplikasi pemrosesan data tradisional. Analisis Big Data bertujuan untuk menemukan wawasan dan pola tersembunyi.','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sistem yang mengelola sertifikat digital dan pasangan kunci publik-privat, yang menjadi dasar kepercayaan dalam komunikasi aman di internet, disebut...','[{"key": "A", "text": "Key Distribution Center (KDC)"}, {"key": "B", "text": "Public Key Infrastructure (PKI)"}, {"key": "C", "text": "Certificate Authority (CA)"}, {"key": "D", "text": "Hashing Management System (HMS)"}]'::jsonb,'C','HMI adalah komponen dari sistem SCADA yang menyajikan data proses kepada operator manusia dalam bentuk grafis (diagram, alarm, tren) dan memungkinkan operator untuk berinteraksi dengan sistem kontrol.','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam arsitektur client-server, peran utama server adalah...','[{"key": "A", "text": "Hanya untuk menampilkan antarmuka pengguna."}, {"key": "B", "text": "Memulai permintaan komunikasi data."}, {"key": "C", "text": "Menyediakan, mengelola, dan memproses sumber daya atau layanan."}, {"key": "D", "text": "Menerjemahkan nama domain menjadi alamat IP."}]'::jsonb,'B','PLC adalah komputer industri tangguh yang dirancang untuk mengotomatisasi proses elektromekanis. Di gardu induk, PLC dapat diprogram untuk menjalankan logika kontrol untuk peralatan seperti pemutus sirkuit (circuit breaker).','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Penggunaan metode HTTP seperti GET, POST, PUT, dan DELETE untuk operasi data merupakan salah satu prinsip dari arsitektur API...','[{"key": "A", "text": "SOAP"}, {"key": "B", "text": "RPC"}, {"key": "C", "text": "GraphQL"}, {"key": "D", "text": "REST"}]'::jsonb,'C','Sensor adalah komponen dasar dari sistem IoT. Fungsinya adalah untuk merasakan atau mengukur kondisi di lingkungan fisik dan mengubah informasi tersebut menjadi data digital yang dapat dikirim dan diproses.','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sistem terdistribusi (distributed system) adalah...','[{"key": "A", "text": "Sebuah sistem komputasi tunggal yang sangat kuat dan sepenuhnya terpusat pada satu lokasi."}, {"key": "B", "text": "Kumpulan komputer independen yang tampak bagi penggunanya sebagai satu sistem koheren."}, {"key": "C", "text": "Sebuah database terpusat yang hanya bisa diakses secara eksklusif oleh satu pengguna saja."}, {"key": "D", "text": "Sebuah arsitektur di mana seluruh logika pemrosesan datanya hanya terjadi di sisi klien."}]'::jsonb,'A','Data telemetri adalah data pengukuran yang dikirim dari lokasi terpencil. Dalam konteks smart meter, data operasional seperti tegangan, arus, frekuensi, dan faktor daya adalah contoh data telemetri yang dikirim ke pusat data PLN.','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Modul dalam sistem ERP PLN yang bertanggung jawab untuk mengelola siklus hidup aset fisik perusahaan, mulai dari pengadaan, pemeliharaan, hingga penghapusan gardu atau trafo, adalah...','[{"key": "A", "text": "Human Resource Management (HRM)"}, {"key": "B", "text": "Financial Accounting (FI)"}, {"key": "C", "text": "Supply Chain Management (SCM)"}, {"key": "D", "text": "Enterprise Asset Management (EAM)"}]'::jsonb,'C','Seiring dengan semakin terhubungnya sistem kontrol industri (SCADA) dan IoT ke jaringan, mereka menjadi target bagi serangan siber. Kompromi pada sistem ini dapat memiliki dampak fisik yang parah, seperti mengganggu pasokan listrik.','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kumpulan data besar yang terstruktur dan tidak terstruktur yang dianalisis secara komputasional untuk mengungkap pola, tren, dan asosiasi, terutama yang berkaitan dengan perilaku dan interaksi manusia, disebut...','[{"key": "A", "text": "Database Relasional"}, {"key": "B", "text": "Data Warehouse"}, {"key": "C", "text": "Spreadsheet"}, {"key": "D", "text": "Big Data"}]'::jsonb,'B','DNP3 (Distributed Network Protocol 3) adalah seperangkat protokol komunikasi yang umum digunakan antara komponen di sistem otomasi proses, terutama di perusahaan utilitas seperti listrik dan air.','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Antarmuka grafis dalam sistem SCADA yang memungkinkan operator di pusat kendali untuk memantau dan mengendalikan proses di lapangan secara visual adalah...','[{"key": "A", "text": "RTU (Remote Terminal Unit)"}, {"key": "B", "text": "PLC (Programmable Logic Controller)"}, {"key": "C", "text": "HMI (Human-Machine Interface)"}, {"key": "D", "text": "Server Database"}]'::jsonb,'D','Platform Cloud menyediakan infrastruktur yang skalabel dan kuat untuk menangani volume data yang sangat besar (Big Data) yang dihasilkan oleh perangkat IoT. Di sana, data dapat disimpan, diproses, dan dianalisis untuk mendapatkan wawasan operasional.','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perangkat kontrol industri yang dapat diprogram untuk melakukan tugas otomasi, seperti mengontrol pembukaan dan penutupan sirkuit di gardu induk, adalah...','[{"key": "A", "text": "HMI (Human-Machine Interface)"}, {"key": "B", "text": "PLC (Programmable Logic Controller)"}, {"key": "C", "text": "Sensor"}, {"key": "D", "text": "Router"}]'::jsonb,'D','Berbeda dengan sensor yang mengumpulkan data dari lingkungan, aktuator menerima perintah (sinyal) dari sistem kontrol dan melakukan tindakan di dunia fisik. Contohnya adalah motor yang membuka katup atau relay yang memutuskan sirkuit listrik.','AKDING',40);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perangkat fisik dalam sistem IoT yang berfungsi untuk mendeteksi atau mengukur suatu besaran fisik (seperti suhu, tegangan, atau arus) dan mengubahnya menjadi sinyal yang dapat dibaca adalah...','[{"key": "A", "text": "Actuator"}, {"key": "B", "text": "Gateway"}, {"key": "C", "text": "Sensor"}, {"key": "D", "text": "Cloud"}]'::jsonb,'A','','AKDING',41);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam konteks smart meter di rumah pelanggan, data seperti faktor daya (power factor) dan tegangan (voltage) merupakan contoh dari data...','[{"key": "A", "text": "Telemetri"}, {"key": "B", "text": "Konfigurasi"}, {"key": "C", "text": "Metadata"}, {"key": "D", "text": "Log Error"}]'::jsonb,'A','','AKDING',42);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Salah satu tantangan keamanan terbesar pada sistem SCADA dan IoT di jaringan kelistrikan adalah...','[{"key": "A", "text": "Keterbatasan pada kapasitas bandwidth internet yang tersedia untuk komunikasi data."}, {"key": "B", "text": "Tingginya biaya implementasi awal karena harga sensor IoT yang masih sangat mahal."}, {"key": "C", "text": "Kerentanan terhadap serangan siber yang dapat menyebabkan pemadaman luas."}, {"key": "D", "text": "Adanya kesulitan teknis dalam melakukan proses pembaruan perangkat lunak (update)"}]'::jsonb,'A','','AKDING',43);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Selain Modbus, protokol komunikasi lain yang umum digunakan pada sistem SCADA di industri kelistrikan karena kemampuannya melaporkan data berdasarkan perubahan (report-by-exception) adalah...','[{"key": "A", "text": "HTTP"}, {"key": "B", "text": "DNP3"}, {"key": "C", "text": "FTP"}, {"key": "D", "text": "SMTP"}]'::jsonb,'A','','AKDING',44);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Peran platform Cloud dalam implementasi IoT untuk smart grid PLN adalah...','[{"key": "A", "text": "Bertujuan untuk menggantikan semua fungsi utama dari sebuah gardu induk listrik."}, {"key": "B", "text": "Berfungsi utama untuk menyediakan pasokan cadangan tenaga listrik saat pemadaman."}, {"key": "C", "text": "Dibatasi perannya hanya sebagai antarmuka bagi pelanggan untuk pembayaran tagihan."}, {"key": "D", "text": "Sebagai pusat pengumpulan, penyimpanan, dan analisis data dari jutaan sensor."}]'::jsonb,'A','','AKDING',45);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah aktuator (actuator) dalam sistem IoT/SCADA berbeda dengan sensor karena aktuator...','[{"key": "A", "text": "Hanya mengirim data."}, {"key": "B", "text": "Membutuhkan daya yang lebih kecil."}, {"key": "C", "text": "Mengukur besaran fisik."}, {"key": "D", "text": "Menerima sinyal dan melakukan tindakan fisik."}]'::jsonb,'A','','AKDING',46);
